/** Limits a number to the range [min, max]. */
export function clamp(value: number, min: number, max: number): number {
  if (min > max) throw new RangeError(`min (${min}) must be <= max (${max})`);
  return Math.min(Math.max(value, min), max);
}
EOF
cat > test/clamp.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { clamp } from '../src/clamp.ts';

test('returns the value when it is within the range', () => {
  assert.equal(clamp(5, 0, 10), 5);
});

test('limits values below and above the range', () => {
  assert.equal(clamp(-3, 0, 10), 0);
  assert.equal(clamp(42, 0, 10), 10);
});

test('rejects an empty range', () => {
  assert.throws(() => clamp(5, 10, 0), RangeError);
});
EOF
